function Assert-QPath([string]$Path,[switch]$New) {
 if([string]::IsNullOrWhiteSpace($Path)){throw 'A local path is required.'};$full=[IO.Path]::GetFullPath($Path);if($full.StartsWith('\\')){throw 'Local paths only.'}
 if($New -and (Test-Path -LiteralPath $full)){throw 'Destination already exists.'}
 $cursor=$full;while($cursor){if(Test-Path -LiteralPath $cursor){$item=Get-Item -LiteralPath $cursor -Force;if($item.Attributes -band [IO.FileAttributes]::ReparsePoint){throw 'Reparse points are refused.'}};$next=[IO.Path]::GetDirectoryName($cursor);if($next -eq $cursor){break};$cursor=$next};$full
}
function Read-QJson([string]$Path) {$p=Assert-QPath $Path;$f=Get-Item -LiteralPath $p;if($f.PSIsContainer -or $f.Length -gt 4194304){throw 'JSON must be a file no larger than 4 MiB.'};$v=Get-Content -LiteralPath $p -Raw -Encoding utf8|ConvertFrom-Json -AsHashtable -Depth 50;if($v -isnot [Collections.IDictionary]){throw 'JSON root must be an object.'};$v}
function Assert-QInteger($Value,[long]$Min,[long]$Max,[string]$Name) {if(($Value -isnot [int] -and $Value -isnot [long] -and $Value -isnot [Numerics.BigInteger]) -or $Value -lt $Min -or $Value -gt $Max){throw "Invalid integer: $Name"};[long]$Value}
function Assert-QSchema($Object) {if(-not $Object.Contains('schemaVersion') -or (Assert-QInteger $Object.schemaVersion 1 1 'schemaVersion') -ne 1){throw 'schemaVersion must be integer 1.'}}
function Resolve-QChild([string]$Root,[string]$Relative) {if([string]::IsNullOrWhiteSpace($Relative) -or [IO.Path]::IsPathRooted($Relative) -or $Relative -match '[:*?\x00-\x1f]'){throw 'Invalid relative path.'};$base=Assert-QPath $Root;$full=Assert-QPath (Join-Path $base $Relative);if(-not $full.StartsWith($base.TrimEnd('\','/')+[IO.Path]::DirectorySeparatorChar,[StringComparison]::OrdinalIgnoreCase)){throw 'Path escapes declared root.'};$full}
function Get-QFiles([string]$Root) {$base=Assert-QPath $Root;$q=[Collections.Generic.Queue[string]]::new();$q.Enqueue($base);$result=[Collections.Generic.List[object]]::new();$count=0;$bytes=0L;while($q.Count){foreach($item in Get-ChildItem -LiteralPath $q.Dequeue() -Force){if(++$count -gt 10000){throw 'Fixture tree exceeds 10000 entries.'};if($item.Attributes -band [IO.FileAttributes]::ReparsePoint){throw 'Reparse fixture entry refused.'};if($item.PSIsContainer){$q.Enqueue($item.FullName)}else{$bytes+=$item.Length;if($bytes -gt 134217728){throw 'Fixture exceeds 128 MiB.'};$result.Add($item)}}};$result.ToArray()}
function Get-QTreeHash([string]$Root) {$map=[Collections.Generic.SortedDictionary[string,string]]::new([StringComparer]::Ordinal);foreach($f in Get-QFiles $Root){$map.Add([IO.Path]::GetRelativePath($Root,$f.FullName),(Get-FileHash -LiteralPath $f.FullName -Algorithm SHA256).Hash)};ConvertTo-QCanonical $map}
function ConvertTo-QCanonical($Value) {if($null -eq $Value){return 'null'};if($Value -is [Collections.IDictionary]){$keys=[Collections.Generic.List[string]]::new();foreach($k in $Value.Keys){$keys.Add([string]$k)};$keys.Sort([StringComparer]::Ordinal);$pairs=foreach($k in $keys){(ConvertTo-Json -InputObject $k -Compress)+':'+(ConvertTo-QCanonical $Value[$k])};return '{'+($pairs -join ',')+'}'};if($Value -is [array]){$items=foreach($x in $Value){ConvertTo-QCanonical $x};return '['+($items -join ',')+']'};ConvertTo-Json -InputObject $Value -Compress -Depth 50}
function Get-QPointer($Value,[string]$Pointer) {if($Pointer -eq ''){return @{exists=$true;value=$Value}};if(-not $Pointer.StartsWith('/')){throw 'JSON pointer must be empty or begin with /.'};$node=$Value;foreach($part in $Pointer.Substring(1).Split('/')){$key=$part.Replace('~1','/').Replace('~0','~');if($node -is [Collections.IDictionary]){if(-not $node.Contains($key)){return @{exists=$false;value=$null}};$node=$node[$key]}elseif($node -is [array] -and $key -match '^(0|[1-9][0-9]*)$' -and [Numerics.BigInteger]::Parse($key) -lt $node.Length){$node=$node[[int]$key]}else{return @{exists=$false;value=$null}}};@{exists=$true;value=$node}}
function Invoke-QProcess([string]$Exe,[string[]]$Arguments,[string]$WorkingDirectory,[int]$Timeout=20,[int]$Limit=2097152) {if(-not ('LocalDevTools.PlatformProcess' -as [type])){Add-Type -Path (Join-Path $PSScriptRoot 'PlatformResources.cs')};$actual=(Get-Command -Name $Exe -CommandType Application -ErrorAction Stop|Select-Object -First 1).Source;if([IO.Path]::GetExtension($actual) -ine '.exe'){throw 'Native executable required; select pwsh explicitly for scripts.'};[LocalDevTools.PlatformProcess]::Run($actual,$Arguments,$WorkingDirectory,$Timeout,$Limit)}
function New-QResult([string]$Tool,[string]$Scope) {[ordered]@{schemaVersion=1;observedUtc=[DateTime]::UtcNow.ToString('o');tool=$Tool;scope=$Scope;status='Unknown';valid=$false;findings=@();artifacts=@();executionEvidence=@();limitations=@();error=$null}}
function Complete-QResult($Result,[switch]$Json) {if($Json){ConvertTo-Json -InputObject $Result -Depth 50}else{[pscustomobject]$Result}}
